def entries():
 result=[]
 for source,raw in RAW.items():
  for i,line in enumerate(raw.splitlines(),1):
   title,focus,task,related=line.split('|')
   result.append(dict(id=f'{source}-{i:02}',source=source,title=title,focus=focus,task=task,related=related))
 return result
